package com.hbm.client.gascentrifuge;
import com.hbm.machine.gascentrifuge.*;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.*;
@EventBusSubscriber(modid="hbm",value=Dist.CLIENT,bus=EventBusSubscriber.Bus.MOD)
public final class GasCentrifugeClient {
 @SubscribeEvent public static void setup(net.neoforged.fml.event.lifecycle.FMLClientSetupEvent event){event.enqueueWork(()->{GasCentrifugeBlockEntity.CLIENT_TICK=GasCentrifugeSound::clientTick;GasCentrifugeBlockEntity.CLIENT_REMOVED=GasCentrifugeSound::removed;});}@SubscribeEvent public static void renderers(EntityRenderersEvent.RegisterRenderers event){event.registerBlockEntityRenderer(GasCentrifugeContent.ENTITY.get(),GasCentrifugeRenderer::new);}@SubscribeEvent public static void screens(RegisterMenuScreensEvent event){event.register(GasCentrifugeContent.MENU.get(),GasCentrifugeScreen::new);}@SubscribeEvent public static void extensions(net.neoforged.neoforge.client.extensions.common.RegisterClientExtensionsEvent event){event.registerItem(new net.neoforged.neoforge.client.extensions.common.IClientItemExtensions(){private GasCentrifugeItemRenderer renderer;@Override public net.minecraft.client.renderer.BlockEntityWithoutLevelRenderer getCustomRenderer(){if(renderer==null)renderer=new GasCentrifugeItemRenderer();return renderer;}},GasCentrifugeContent.ITEM.get());}private GasCentrifugeClient(){}
}
